# 用户端只呈现统一栏目，不区分采集来源。
def rows(text: str, fields: tuple[str, ...]) -> list[dict[str, str]]:
    return [
        dict(zip(fields, line.split("|")))
        for line in text.strip().splitlines()
        if line.strip()
    ]


